def vintage_rows(rows,cutoff):
    # Synthetic schema:(permanent_asset_id,observation_time,available_time,revision,value_cents).
    if type(cutoff) is not int or cutoff<0 or type(rows) is not list or len(rows)>128:
        raise ValueError("invalid snapshot boundary")
    seen=set();groups={}
    for row in rows:
        if type(row) is not tuple or len(row)!=5:raise ValueError("invalid revision row")
        asset,obs,available,revision,value=row
        if type(asset) is not str or not asset or any(type(x) is not int for x in row[1:]):
            raise ValueError("invalid revision types")
        if not 0<=obs<=available or revision<0 or value<=0:
            raise ValueError("invalid revision domain")
        key=(asset,obs,revision)
        if key in seen:raise ValueError("duplicate revision key")
        seen.add(key);groups.setdefault((asset,obs),[]).append(row)
    for group in groups.values():
        ordered=sorted(group,key=lambda row:row[3])
        if any(a[2]>b[2] for a,b in zip(ordered,ordered[1:])):
            raise ValueError("revision availability runs backward")
    chosen={}
    for row in rows:
        asset,obs,available,revision,value=row
        if available>cutoff:continue
        key=(asset,obs)
        if key not in chosen or (available,revision)>(chosen[key][2],chosen[key][3]):chosen[key]=row
    return tuple(chosen[key] for key in sorted(chosen))

history=[("A",1,2,0,100),("A",1,5,1,120),("B",1,2,0,200),("A",3,4,0,110)]
print(vintage_rows(history,3))
print(vintage_rows(history,5))
try:vintage_rows(history+[history[0]],5)
except ValueError as error:print(error)
